// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/settings/McpShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Settings → Connections → MCP integrations, ported from the app's McpMenu
 * (src/panels/McpMenu.tsx) with its AsyncButton: app window control allowed,
 * the local app as the connection, both devices' integration health, and the
 * agent clients the server can be added to.
 */
import { Check, Copy, Download, RefreshCw, type LucideIcon } from "lucide-react";
import type { ReactNode } from "react";
import { SettingsWindow } from "./SettingsWindow";

/** The frameworks the app's server offers, in its order (server/lib/mcp.js). */
const FRAMEWORKS: { key: string; label: string; note?: string }[] = [
  { key: "claude", label: "Claude Code", note: "added ✓" },
  { key: "codex", label: "Codex" },
  { key: "opencode", label: "OpenCode" },
  { key: "cursor", label: "Cursor" },
  { key: "windsurf", label: "Windsurf" },
  { key: "zed", label: "Zed" },
];

const DEVICES = ["This Device", "Devbox"];

/** Where the bundled app's server resolves the MCP script (server/lib/config.js MCP_PATH). */
const MCP_PATH = "/Applications/PzzaCode.app/Contents/Resources/mcp/server.js";

/** The app's AsyncButton at rest (src/ui/AsyncButton.tsx). */
function AsyncButton({ className, icon: Icon, iconSize = 14, children }: { className: string; icon: LucideIcon; iconSize?: number; children: ReactNode }) {
  return (
    <button type="button" className={`${className} async-button`} aria-busy={false}>
      <span className="async-button-icon" style={{ width: iconSize, height: iconSize }} aria-hidden="true">
        <Icon size={iconSize} strokeWidth={2} />
      </span>
      {children}
    </button>
  );
}

function McpPage() {
  return (
    <div>
      <div className="settings-page mcp-settings">
        <div className="settings-row">
          <div className="settings-row-copy">
            <span>Allow app window control</span>
            <small>Control sessions, workspaces, editors, and app settings.</small>
          </div>
          <button className="switch switch-on" role="switch" aria-label="Allow app window control" aria-checked>
            <span className="switch-knob" />
          </button>
        </div>

        <p className="set-note">
          File, device and session tools remain available when window control is off, except ending a session: the user confirms that in an app window with window control on.
        </p>
        <section className="settings-section" aria-label="Connection">
          <div className="settings-form">
            <label className="settings-field">
              <span>App SSH host</span>
              <input className="field-input" value="" placeholder="Local app (default)" spellCheck={false} readOnly />
              <small>Optional SSH target for an app on another device.</small>
            </label>
          </div>
        </section>
        <section className="settings-section" aria-label="Integration health">
          <div className="settings-row">
            <div className="settings-row-copy">
              <span>Automatic startup repairs</span>
              <small>Check installed server commands on each device every minute. Preserve configuration and private backups when a repair is needed.</small>
            </div>
            <AsyncButton className="btn btn-sm" icon={RefreshCw}>
              Check now
            </AsyncButton>
          </div>
          {DEVICES.map((name) => (
            <details key={name} className="settings-disclosure">
              <summary>{name} · Ready</summary>
            </details>
          ))}
        </section>
        <section className="settings-section" aria-label="Integrations">
          <h3 className="set-title">Integrations</h3>
          <div className="mcp-list">
            {FRAMEWORKS.map(({ key, label, note }) => (
              <div key={key} className="settings-row mcp-row">
                <div className="settings-row-copy">
                  <span>{label}</span>
                  {note ? <small role="status">{note}</small> : null}
                </div>
                <div className="settings-actions">
                  <AsyncButton className="btn btn-accent btn-sm" icon={Download} iconSize={13}>
                    Add
                  </AsyncButton>
                  <button className="btn btn-sm" title="Copy configuration" aria-label={`Copy ${label} configuration`}>
                    <Copy size={13} strokeWidth={2} /> Copy
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
        <p className="set-note mcp-path" title={MCP_PATH}>
          <Check size={11} strokeWidth={2.5} /> server: {MCP_PATH}
        </p>
      </div>
    </div>
  );
}

// The page is taller than the dialog; the scene shows it scrolled down to the
// client list, which is what the page is for.
const INTEGRATIONS = 'section[aria-label="Integrations"] > .set-title';

export function McpShot() {
  return (
    <SettingsWindow section="mcp" page="mcp" scrollTo={INTEGRATIONS}>
      <McpPage />
    </SettingsWindow>
  );
}
